/**
 * engine-server/pipeline/evidence-chain.ts — 证据链导出（壁垒四核心）
 *
 * 为 BlueprintDTO 生成可导出的证据追溯链。
 * 每条 mentalModel 的 source → framework-library 条目 → 原始信源出处
 *
 * @date 2026-05-14
 */
import type { PersonaGenomeBlue } from '../types';
export interface EvidenceLink {
    /** 心智模型名称 */
    mentalModel: string;
    /** LLM 输出的 source 字段 */
    sourceId: string;
    /** 框架库中的完整条目（如有） */
    framework?: {
        id: string;
        name: string;
        category: string;
        coreInsight: string;
        limitations: string[];
    };
    /** 弹药库中的领域知识（如有） */
    ammoEntry?: {
        id: string;
        industry: string;
        factText: string;
        confidence: string;
        sources?: string[];
    };
    /** 追踪链完整性 */
    traceCompleteness: 'full' | 'partial' | 'none';
}
export interface EvidenceChain {
    roleId: string;
    roleName: string;
    links: EvidenceLink[];
}
/**
 * 为所有角色构建证据追溯链。
 */
export declare function buildEvidenceChain(personaGenomes: PersonaGenomeBlue[], matchedAmmoIds: Set<string>): EvidenceChain[];
/**
 * 统计证据链完整性
 */
export declare function summarizeEvidenceChain(chains: EvidenceChain[]): {
    totalLinks: number;
    full: number;
    partial: number;
    none: number;
};
